/*
 * O estado de uma tabela de usuários (diretório /u ou membros de um grupo):
 * filtros, as páginas já carregadas e o "carregar mais".
 */

import { fetchDirectory, pushUsers } from './api';
export default class DirectoryState {
  rows = [];
  columns = [];
  total = null;
  hasMore = false;
  loading = false;
  failed = false;

  /** Respostas que chegam fora de ordem (busca digitada rápido) são descartadas. */
  requestId = 0;
  constructor(params) {
    this.params = {
      ...params
    };
  }

  /** Troca filtros e recomeça da primeira página. */
  refresh(changes = {}) {
    this.params = {
      ...this.params,
      ...changes,
      page: 1
    };
    this.rows = [];
    this.hasMore = false;
    return this.load();
  }
  loadMore() {
    if (this.loading || !this.hasMore) return Promise.resolve();
    this.params = {
      ...this.params,
      page: (this.params.page || 1) + 1
    };
    return this.load();
  }

  /** Clicar na coluna já ordenada inverte o sentido; numa nova, começa do maior. */
  sortBy(column) {
    const same = this.currentOrder() === column;
    const dir = same ? this.params.dir === 'asc' ? 'desc' : 'asc' : column === 'username' ? 'asc' : 'desc';
    return this.refresh({
      order: column,
      dir
    });
  }
  setPeriod(period) {
    return this.refresh({
      period
    });
  }
  currentOrder() {
    return this.params.order;
  }
  load() {
    const id = ++this.requestId;
    this.loading = true;
    this.failed = false;
    m.redraw();
    return fetchDirectory(this.params).then(payload => {
      if (id !== this.requestId) return;
      const users = pushUsers(payload.included || []);
      const rows = payload.data.map(row => ({
        ...row,
        model: users[row.user]
      })).filter(row => !!row.model);
      this.rows = payload.meta.page > 1 ? [...this.rows, ...rows] : rows;
      this.columns = payload.meta.columns;
      this.total = payload.meta.total;
      this.hasMore = payload.meta.hasMore;

      // O servidor devolve a ordenação que valeu (um parâmetro inválido cai
      // no padrão): o cabeçalho marca a coluna certa.
      this.params = {
        ...this.params,
        order: payload.meta.order,
        dir: payload.meta.dir,
        period: payload.meta.period
      };
    }).catch(() => {
      if (id === this.requestId) this.failed = true;
    }).finally(() => {
      if (id !== this.requestId) return;
      this.loading = false;
      m.redraw();
    });
  }
}
flarum.reg.add('ramon-canela', 'forum/features/community/DirectoryState', DirectoryState);