import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import Icon from 'flarum/common/components/Icon';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import classList from 'flarum/common/utils/classList';
import formatNumber from 'flarum/common/utils/formatNumber';
import UserTile from './UserTile';
import { t } from '../../utils/settings';
import { shortAge } from '../../utils/dates';

/** Ícone de cada coluna, como os do cabeçalho do diretório do Discourse. */
const COLUMN_ICONS = {
  likesReceived: 'fas fa-heart',
  likesGiven: 'fas fa-heart'
};

/** Colunas numéricas que vêm na linha (as outras saem do modelo do usuário). */
const NUMERIC = ['likesReceived', 'likesGiven', 'topicCount', 'postCount', 'daysVisited', 'postsRead'];
/**
 * A tabela do diretório do Discourse: usuário à esquerda, uma coluna por
 * número, cabeçalhos clicáveis para ordenar e "carregar mais" no fim.
 *
 * "Último acesso" sempre aparece (quando o usuário o divulga), mas só ordena
 * para quem tem a permissão do core — o servidor diz quais colunas ordenam.
 */
export default class DirectoryTable extends Component {
  view() {
    const {
      state,
      emptyText
    } = this.attrs;
    const columns = this.displayColumns();
    if (state.failed && !state.rows.length) {
      return m("p", {
        className: "CanelaCommunity-empty"
      }, t('community.load_error'));
    }
    if (!state.loading && !state.rows.length && state.total !== null) {
      return m("p", {
        className: "CanelaCommunity-empty"
      }, state.params.q ? t('community.users.no_results') : emptyText);
    }
    return m("div", {
      className: "CanelaDirectory"
    }, m("div", {
      className: "CanelaCommunity-tableWrap"
    }, m("table", {
      className: "CanelaCommunity-table CanelaDirectory-table"
    }, m("thead", null, m("tr", null, this.header('username', t('community.users.column.username'), 'CanelaDirectory-userCol'), columns.map(column => this.header(column, t(`community.users.column.${column}`), 'CanelaCommunity-num')))), m("tbody", null, state.rows.map(row => this.row(row, columns))))), state.loading && m(LoadingIndicator, {
      display: "block"
    }), !state.loading && state.hasMore && m("div", {
      className: "CanelaCommunity-more"
    }, m(Button, {
      className: "Button",
      onclick: () => state.loadMore()
    }, t('community.load_more'))));
  }

  /** As colunas do servidor, mais "Último acesso" quando ele não ordena por ela. */
  displayColumns() {
    const columns = [...this.attrs.state.columns];
    if (!columns.includes('lastSeenAt')) columns.push('lastSeenAt');
    return columns;
  }
  header(column, label, className) {
    const {
      state
    } = this.attrs;
    const sortable = column === 'username' || state.columns.includes(column);
    const active = state.currentOrder() === column;
    const icon = COLUMN_ICONS[column];
    const content = m('[', null, icon && m(Icon, {
      name: icon,
      className: "CanelaDirectory-columnIcon"
    }), m("span", null, label), active && m(Icon, {
      name: state.params.dir === 'asc' ? 'fas fa-chevron-up' : 'fas fa-chevron-down',
      className: "CanelaDirectory-sortIcon"
    }));
    return m("th", {
      className: classList(className, `CanelaDirectory-col--${column}`, {
        'is-sorted': active
      }),
      "aria-sort": active ? state.params.dir === 'asc' ? 'ascending' : 'descending' : undefined,
      scope: "col"
    }, sortable ? m("button", {
      type: "button",
      className: "CanelaDirectory-sort",
      onclick: () => state.sortBy(column)
    }, content) : m("span", {
      className: "CanelaDirectory-sort is-static"
    }, content));
  }
  row(row, columns) {
    const user = row.model;
    const isMe = app.session.user === user;
    return m("tr", {
      key: row.user,
      className: classList({
        'is-me': isMe
      })
    }, m("td", {
      className: "CanelaDirectory-userCol"
    }, m(UserTile, {
      user: user,
      size: "small"
    })), columns.map(column => m("td", {
      className: `CanelaCommunity-num CanelaDirectory-value CanelaDirectory-col--${column}`,
      "data-label": t(`community.users.column.${column}`)
    }, this.value(row, column))));
  }
  value(row, column) {
    if (NUMERIC.includes(column)) {
      const value = row[column];
      return typeof value === 'number' ? formatNumber(value) : '-';
    }
    if (column === 'lastSeenAt') {
      const seen = row.model.lastSeenAt();
      return seen ? m("time", {
        datetime: seen.toISOString(),
        title: seen.toLocaleString()
      }, shortAge(seen)) : '-';
    }
    return null;
  }
}
flarum.reg.add('ramon-canela', 'forum/features/community/DirectoryTable', DirectoryTable);